

import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from .function_call_output_output import FunctionCallOutputOutput
from .function_call_output_status import FunctionCallOutputStatus


class FunctionCallOutput(UniversalBaseModel):
    """
    A function tool call output that was returned by the tool.
    """

    id: str = pydantic.Field()
    """
    The unique ID of the function tool call output. Populated when this item is returned via API.
    """

    call_id: str = pydantic.Field()
    """
    The unique ID of the function tool call generated by the model.
    """

    output: FunctionCallOutputOutput
    status: FunctionCallOutputStatus = pydantic.Field()
    """
    The status of the item. One of `in_progress`, `completed`, or `incomplete`. Populated when items are returned via API.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
